public class Message { private final int id; private final User sender,receiver; private final String content; public Message(int id,User sender,User receiver,String content){this.id=id;this.sender=sender;this.receiver=receiver;this.content=content;} public int getId(){return id;} public User getSender(){return sender;} public User getReceiver(){return receiver;} public String getContent(){return content;} }
